  const maskCache = Object.create(null);

  function mask(name) {
    const key = Object.prototype.hasOwnProperty.call(svg, name) ? name : "info";
    return (maskCache[key] ||= `url("data:image/svg+xml,${encodeURIComponent(svg[key])}")`);
  }

  function el(name, size = 14.4) {
    const span = document.createElement("span");
    span.setAttribute("aria-hidden", "true");
    const m = mask(name);
    span.style.cssText =
      `flex:none;display:inline-block;width:${size}px;height:${size}px;background-color:currentColor;` +
      `-webkit-mask:${m} center/contain no-repeat;mask:${m} center/contain no-repeat;`;
    return span;
  }

  function cssVars(names) {
    return names.map((name) => `--pai-i-${name}:${mask(name)};`).join("");
  }

  globalThis.PaiIcons = { svg, mask, el, cssVars };
